const express  = require('express');
const fetch    = require('node-fetch');
const fs       = require('fs');
const path     = require('path');
const { generateLPPdf } = require('./pdfgen');

// Inject logo into pdfgen environment
process.env.QV_LOGO_B64 = '';

const app  = express();
const PORT = process.env.PORT || 3000;
const SETTINGS_FILE = path.join(__dirname, '.settings.json');

app.use(express.json({ limit: '2mb' }));
app.use(express.static(path.join(__dirname, 'public')));

// ── Settings persistence ───────────────────────────────────────────────────
function readSaved() {
  try { return JSON.parse(fs.readFileSync(SETTINGS_FILE, 'utf8')); } catch { return {}; }
}
function writeSaved(obj) {
  try { fs.writeFileSync(SETTINGS_FILE, JSON.stringify(obj, null, 2)); } catch {}
}
function getCredentials() {
  const s = readSaved();
  return {
    airtableKey:  process.env.AIRTABLE_KEY   || s.airtableKey  || '',
    anthropicKey: process.env.ANTHROPIC_KEY  || s.anthropicKey || '',
    baseId:       process.env.AIRTABLE_BASE  || s.baseId       || '',
    tableName:    process.env.AIRTABLE_TABLE || s.tableName    || '',
    fieldMap:     s.fieldMap || {},
  };
}

// ── Password middleware ────────────────────────────────────────────────────
const APP_PASSWORD = process.env.APP_PASSWORD || '';
app.use((req, res, next) => {
  if (!APP_PASSWORD) return next();
  if (req.path === '/api/auth') return next();
  const token = req.headers['x-app-token'] || req.query.token;
  if (token === APP_PASSWORD) return next();
  res.status(401).json({ error: 'Unauthorized' });
});
app.post('/api/auth', (req, res) => {
  if (!APP_PASSWORD || req.body.password === APP_PASSWORD) res.json({ ok: true });
  else res.status(401).json({ error: 'Wrong password' });
});

// ── Settings endpoints ─────────────────────────────────────────────────────
app.get('/api/settings', (req, res) => {
  const s = readSaved();
  res.json({ airtableKey: s.airtableKey||'', baseId: s.baseId||'',
             tableName: s.tableName||'', anthropicKey: s.anthropicKey||'',
             fieldMap: s.fieldMap||{} });
});
app.post('/api/settings', (req, res) => {
  const s = readSaved();
  const updated = { ...s, ...req.body };
  writeSaved(updated);
  res.json({ ok: true });
});

// ── Airtable proxy ─────────────────────────────────────────────────────────
app.get('/api/airtable', async (req, res) => {
  const { quarter, fund } = req.query;
  const creds = getCredentials();
  if (!creds.airtableKey) return res.status(400).json({ error: 'Airtable API key not configured.' });
  if (!creds.baseId)      return res.status(400).json({ error: 'Airtable Base ID not configured.' });
  if (!creds.tableName)   return res.status(400).json({ error: 'Airtable table name not configured.' });

  const selectedFund = fund || 'Fund I';

  try {
    let url = `https://api.airtable.com/v0/${creds.baseId}/${encodeURIComponent(creds.tableName)}`;
    const fundFilter    = `OR({Fund}="${selectedFund}",{Fund}="Both")`;
    const quarterFilter = quarter ? `{Quarter}="${quarter}"` : null;
    const formula       = quarterFilter ? `AND(${fundFilter},${quarterFilter})` : fundFilter;
    url += `?filterByFormula=${encodeURIComponent(formula)}`;

    const allRecords = [];
    let offset = null;
    do {
      const pageUrl = offset ? `${url}&offset=${offset}` : url;
      const r = await fetch(pageUrl, {
        headers: { Authorization: `Bearer ${creds.airtableKey}` }
      });
      if (!r.ok) {
        const err = await r.text();
        return res.status(r.status).json({ error: `Airtable error: ${err}` });
      }
      const data = await r.json();
      allRecords.push(...(data.records || []));
      offset = data.offset || null;
    } while (offset);

    const fm = creds.fieldMap || {};
    const g  = (rec, key) => rec.fields[fm[key] || key] || '';

    const companies = allRecords.map(rec => ({
      company:           g(rec, 'Company'),
      quarter:           g(rec, 'Quarter'),
      contactNames:      g(rec, 'Contact Names'),
      companyHealth:     g(rec, 'Company Health'),
      stage:             g(rec, 'Stage'),
      founderMorale:     g(rec, 'Founder Morale (1-10)'),
      quarterSummary:    g(rec, 'Quarter Summary'),
      arr:               g(rec, 'ARR (NZD)'),
      revenueTrend:      g(rec, 'Revenue Trend'),
      cashOnHand:        g(rec, 'Cash on Hand (NZD)'),
      monthlyBurn:       g(rec, 'Monthly Burn (NZD)'),
      runway:            g(rec, 'Runway (Months)'),
      financialNotes:    g(rec, 'Financial Notes'),
      fundraisingStatus: g(rec, 'Fundraising Status'),
      raiseDetails:      g(rec, 'Raise Details'),
      topAsk:            g(rec, 'Top Ask'),
      biggestRisk:       g(rec, 'Biggest Risk'),
      milestonesAchieved:g(rec, 'Milestones Achieved'),
      milestonesMissed:  g(rec, 'Milestones Missed'),
      goalsNextQuarter:  g(rec, 'Goals Next Quarter'),
      headcount:         g(rec, 'Headcount'),
      anythingElse:      g(rec, 'Anything Else'),
      fund:              g(rec, 'Fund'),
    }));

    res.json({ companies });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});


// ── AI Draft (new section from prompt) ────────────────────────────────────────
app.post('/api/draft-section', async (req, res) => {
  const { section, prompt, system } = req.body;
  const creds = getCredentials();
  if (!creds.anthropicKey)
    return res.status(400).json({ error: 'Anthropic API key not configured. Add it in Settings.' });
  if (!prompt)
    return res.status(400).json({ error: 'No prompt provided.' });

  try {
    const r = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'x-api-key': creds.anthropicKey, 'anthropic-version': '2023-06-01',
                 'content-type': 'application/json' },
      body: JSON.stringify({
        model: 'claude-sonnet-4-20250514',
        max_tokens: 1024,
        system: system || 'You are an expert VC communications writer for Quidnet Ventures, a New Zealand seed-stage deep tech fund. Write clear, professional prose. No markdown.',
        messages: [{ role: 'user', content: prompt }]
      })
    });
    if (!r.ok) return res.status(r.status).json({ error: await r.text() });
    const data = await r.json();
    res.json({ draftText: data.content?.[0]?.text?.trim() || '' });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ── AI section improver ────────────────────────────────────────────────────
app.post('/api/improve-section', async (req, res) => {
  const { sectionId, currentText, comment } = req.body;
  const creds = getCredentials();
  if (!creds.anthropicKey) return res.status(400).json({ error: 'Anthropic API key not configured.' });
  if (!currentText) return res.status(400).json({ error: 'No text provided.' });

  const labels = { opening:'the opening letter to LPs', fundraising:'the fundraising update',
                   context:'the market context section' };
  const label = labels[sectionId] || `section "${sectionId}"`;
  const system = 'You are an expert VC communications writer for Quidnet Ventures, a New Zealand seed-stage deep tech fund. '
               + 'Improve LP update sections: substantive, direct, warm but professional. Write in first person plural. '
               + 'Return ONLY the improved text — no preamble, no commentary, no markdown formatting.';
  const user   = comment
    ? `Improve ${label} based on this instruction: "${comment}"\n\nCurrent text:\n${currentText}`
    : `Improve ${label} — clearer, more compelling, preserve all facts.\n\nCurrent text:\n${currentText}`;

  try {
    const r = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'x-api-key': creds.anthropicKey, 'anthropic-version': '2023-06-01',
                 'content-type': 'application/json' },
      body: JSON.stringify({ model: 'claude-sonnet-4-20250514', max_tokens: 1024,
                             system, messages: [{ role: 'user', content: user }] })
    });
    if (!r.ok) return res.status(r.status).json({ error: await r.text() });
    const data = await r.json();
    res.json({ improvedText: data.content?.[0]?.text?.trim() || currentText });
  } catch (e) { res.status(500).json({ error: e.message }); }
});


// ── Draft persistence (Airtable) ──────────────────────────────────────────────
// Drafts are stored in an Airtable table called "LP Drafts" with fields:
//   Draft Key  (Single line text) — unique identifier e.g. "Fund I Q1 2026"
//   Payload    (Long text)        — full JSON state
//   Saved At   (Single line text) — ISO timestamp
//
// The table is created automatically on first save if it doesn't exist,
// but you can also create it manually in Airtable first.

const DRAFTS_TABLE = 'LP Drafts';

async function findDraftRecord(airtableKey, baseId, apiKey, tableName) {
  const url = `https://api.airtable.com/v0/${baseId}/${encodeURIComponent(tableName)}`
            + `?filterByFormula=${encodeURIComponent(`{Draft Key}="${airtableKey}"`)}`;
  const r = await fetch(url, { headers: { Authorization: `Bearer ${apiKey}` } });
  if (!r.ok) return null;
  const data = await r.json();
  return (data.records && data.records[0]) || null;
}

app.post('/api/save-draft', async (req, res) => {
  const creds = getCredentials();
  if (!creds.airtableKey || !creds.baseId)
    return res.status(400).json({ error: 'Airtable not configured. Add API key and Base ID in Settings.' });

  const state    = req.body;
  const draftKey = `${state.fund || 'Fund I'} — ${state.quarter || 'Draft'}`;
  const savedAt  = new Date().toISOString();
  const payload  = JSON.stringify({ ...state, savedAt });

  try {
    // Check if a draft with this key already exists
    const existing = await findDraftRecord(draftKey, creds.baseId, creds.airtableKey, DRAFTS_TABLE);

    if (existing) {
      // Update existing record
      const updateUrl = `https://api.airtable.com/v0/${creds.baseId}/${encodeURIComponent(DRAFTS_TABLE)}/${existing.id}`;
      const r = await fetch(updateUrl, {
        method: 'PATCH',
        headers: { Authorization: `Bearer ${creds.airtableKey}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ fields: { 'Payload': payload, 'Saved At': savedAt } })
      });
      if (!r.ok) throw new Error(await r.text());
    } else {
      // Create new record
      const createUrl = `https://api.airtable.com/v0/${creds.baseId}/${encodeURIComponent(DRAFTS_TABLE)}`;
      const r = await fetch(createUrl, {
        method: 'POST',
        headers: { Authorization: `Bearer ${creds.airtableKey}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ fields: { 'Draft Key': draftKey, 'Payload': payload, 'Saved At': savedAt } })
      });
      if (!r.ok) {
        const errText = await r.text();
        // If table doesn't exist, give a helpful message
        if (errText.includes('Could not find table')) {
          return res.status(400).json({ error: `Airtable table "${DRAFTS_TABLE}" not found. Please create it with fields: Draft Key (Single line text), Payload (Long text), Saved At (Single line text).` });
        }
        throw new Error(errText);
      }
    }

    res.json({ ok: true, savedAt, draftKey });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

app.get('/api/load-draft', async (req, res) => {
  const creds = getCredentials();
  if (!creds.airtableKey || !creds.baseId)
    return res.status(400).json({ error: 'Airtable not configured.' });

  const { fund, quarter } = req.query;

  try {
    const tableUrl = `https://api.airtable.com/v0/${creds.baseId}/${encodeURIComponent(DRAFTS_TABLE)}`
                   + `?sort[0][field]=Saved+At&sort[0][direction]=desc`;
    const r = await fetch(tableUrl, { headers: { Authorization: `Bearer ${creds.airtableKey}` } });
    if (!r.ok) {
      const errText = await r.text();
      if (errText.includes('Could not find table'))
        return res.json({ drafts: [] });
      throw new Error(errText);
    }
    const data = await r.json();
    const drafts = (data.records || []).map(rec => ({
      id:       rec.id,
      draftKey: rec.fields['Draft Key'] || '',
      savedAt:  rec.fields['Saved At']  || '',
    }));
    res.json({ drafts });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

app.get('/api/load-draft/:id', async (req, res) => {
  const creds = getCredentials();
  if (!creds.airtableKey || !creds.baseId)
    return res.status(400).json({ error: 'Airtable not configured.' });

  try {
    const url = `https://api.airtable.com/v0/${creds.baseId}/${encodeURIComponent(DRAFTS_TABLE)}/${req.params.id}`;
    const r = await fetch(url, { headers: { Authorization: `Bearer ${creds.airtableKey}` } });
    if (!r.ok) throw new Error(await r.text());
    const rec  = await r.json();
    const draft = JSON.parse(rec.fields['Payload'] || '{}');
    res.json({ draft });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

app.delete('/api/save-draft/:id', async (req, res) => {
  const creds = getCredentials();
  if (!creds.airtableKey || !creds.baseId)
    return res.status(400).json({ error: 'Airtable not configured.' });
  try {
    const url = `https://api.airtable.com/v0/${creds.baseId}/${encodeURIComponent(DRAFTS_TABLE)}/${req.params.id}`;
    await fetch(url, { method: 'DELETE', headers: { Authorization: `Bearer ${creds.airtableKey}` } });
    res.json({ ok: true });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// ── PDF generation ─────────────────────────────────────────────────────────
app.post('/api/generate', async (req, res) => {
  const payload  = req.body;
  const fund     = (payload.fund || 'Fund I').replace(/ /g, '_');
  const quarter  = (payload.quarter || 'Q').replace(/ /g, '_');
  const filename = `Quidnet_${fund}_${quarter}_LP_Update.pdf`;
  try {
    const pdfBuf = await generateLPPdf(payload);
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
    res.send(pdfBuf);
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.listen(PORT, () => {
  console.log(`\n  Quidnet LP PDF Generator`);
  console.log(`  Running at http://localhost:${PORT}`);
  console.log(`  Password: ${APP_PASSWORD ? 'SET' : 'OFF'}`);
  console.log(`  Airtable: ${getCredentials().airtableKey ? 'SET' : 'NOT SET'}\n`);
});
